"""Migration of Meridian CRM 4.2 credit_hold_sweep.crms."""

from decimal import Decimal
from typing import Any


def _numeric_nvl(value: Any) -> Decimal:
    """Apply legacy NVL numeric semantics: missing/empty values are zero."""
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, str) and value.strip() == "":
        return Decimal("0")
    return Decimal(str(value))


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """
    Apply the nightly credit-hold sweep without mutating input rows.

    Accounts are returned in their supplied order.  Eligible accounts are
    evaluated, and resulting audit events emitted, in ACCT_ID primary-key order.
    """
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    eligible_indexes = [
        index
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]

    for index in sorted(eligible_indexes, key=lambda item: accounts[item].get("ACCT_ID")):
        account = new_accounts[index]
        acct_id = account.get("ACCT_ID")
        exposure = Decimal("0")

        # This preserves the legacy nested FOR EACH document iteration order.
        for order in orders:
            if (
                order.get("ACCT_ID") == acct_id
                and order.get("DEL_FLG") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _numeric_nvl(order.get("TOT_AMT"))

        credit_limit = _numeric_nvl(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        # Deliberately evaluated after the hold-on rule against the updated row.
        if exposure <= credit_limit * Decimal("8") / Decimal("10") and account.get(
            "CRED_HOLD"
        ) == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
